pragma cashscript ^0.14.0;

// BN254 singleton harness `groth16` — the field/pairing arithmetic comes from the shared lib/
// libraries (imported below). See lib/README.md for the structure and how to grade.

import "./lib/Miller.cash";
import "./lib/FinalExp.cash";
import "./lib/G1.cash";

// proof coordinates must be canonical Fp elements (0 <= x < P): congruent values encode the
// same point, so without this every proof has many byte encodings (encoding malleability).
function fpRange(int x) {
    require(within(x, 0, P));
}

contract Groth16Verify() {
    function spend(
        int Ax, int Ay, int Bxa, int Bxb, int Bya, int Byb, int Cx, int Cy,
        int in0, int in1
    ) {
        // ---- public inputs must be canonical scalars: in < r. Without this, in + r gives the
        // same vk_x, so one proof would verify for two different claimed integers (the
        // input-aliasing bug behind nullifier double-spends). ----
        require(within(in0, 0, 21888242871839275222246405745257275088548364400416034343698204186575808495617));
        require(within(in1, 0, 21888242871839275222246405745257275088548364400416034343698204186575808495617));
        // ---- proof coordinates canonical: 0 <= v < P (see fpRange) ----
        fpRange(Ax);
        fpRange(Ay);
        fpRange(Bxa);
        fpRange(Bxb);
        fpRange(Bya);
        fpRange(Byb);
        fpRange(Cx);
        fpRange(Cy);
        // ---- validate spender-supplied proof points (EIP-197 rigor) ----
        require(mulFp(Ay, Ay) == addFp(mulFp(mulFp(Ax, Ax), Ax), 3)); // A on G1
        require(mulFp(Cy, Cy) == addFp(mulFp(mulFp(Cx, Cx), Cx), 3)); // C on G1
        (int bx2a,int bx2b) = fp2Sqr(Bxa, Bxb);                       // B on G2: y^2 == x^3 + b2
        (int bx3a,int bx3b) = fp2Mul(bx2a, bx2b, Bxa, Bxb);
        (int onrhsa,int onrhsb) = fp2Add(bx3a, bx3b,
            19485874751759354771024239261021720505790618469301721065564631296452457478373,
            266929791119991161246907387137283842545076965332900288569378510910307636690);
        (int by2a,int by2b) = fp2Sqr(Bya, Byb);
        require(by2a == onrhsa); require(by2b == onrhsb);
        int RXa=0; int RXb=0; int RYa=1; int RYb=0; int RZa=0; int RZb=0; // [6x^2]B (Jacobian)
        for (int i = 0; i < 128; i = i + 1) {
            (RXa,RXb,RYa,RYb,RZa,RZb) = g2Double(RXa, RXb, RYa, RYb, RZa, RZb);
            if (((147946756881789318990833708069417712966 >> (127 - i)) % 2) == 1) {
                (RXa,RXb,RYa,RYb,RZa,RZb) = g2AddAffine(RXa, RXb, RYa, RYb, RZa, RZb, Bxa, Bxb, Bya, Byb);
            }
        }
        (int psxa,int psxb,int psya,int psyb) = psi(Bxa, Bxb, Bya, Byb); // require [6x^2]B == psi(B)
        (int sz2a,int sz2b) = fp2Sqr(RZa, RZb);
        (int sz3a,int sz3b) = fp2Mul(sz2a, sz2b, RZa, RZb);
        (int cx_a,int cx_b) = fp2Mul(psxa, psxb, sz2a, sz2b);
        (int cy_a,int cy_b) = fp2Mul(psya, psyb, sz3a, sz3b);
        require(RXa == cx_a); require(RXb == cx_b);
        require(RYa == cy_a); require(RYb == cy_b);

        // vk_x = IC0 + in0*IC1 + in1*IC2
        (int r1x, int r1y, int r1z) = g1ScalarMul(in0,
            9269869340829791644953940526610795845982127221382366381974052273854848284744,
            12340830433822638848259976740304056841548514693917037023437897137808450264577);
        (int r2x, int r2y, int r2z) = g1ScalarMul(in1,
            6442706084407552401539720969529928260622245802604045626376932056434206076947,
            13805589277496019078136496656829548863642318729315912795941464570275337353000);
        (int a1x, int a1y, int a1z) = jacAddG1(
            15723390722547469201346605927630336729729463607293657950235977012003655267936,
            14617976463853845616027311884626760527376622737858716767193455441349641383825, 1,
            r1x, r1y, r1z);
        (int vx, int vy, int vz) = jacAddG1(a1x, a1y, a1z, r2x, r2y, r2z);
        (int vkxX, int vkxY) = jacToAffine(vx, vy, vz);

        // e(-A,B) * e(alpha,beta) * e(vk_x,gamma) * e(C,delta) == 1
        int nAy = subFp(0, Ay);
        (int m1_0,int m1_1,int m1_2,int m1_3,int m1_4,int m1_5,int m1_6,int m1_7,int m1_8,int m1_9,int m1_10,int m1_11) =
            millerSingle(Bxa, Bxb, Bya, Byb, Ax, nAy);
        (int m2_0,int m2_1,int m2_2,int m2_3,int m2_4,int m2_5,int m2_6,int m2_7,int m2_8,int m2_9,int m2_10,int m2_11) =
            millerSingle(
                17467917077997409920481960112226002748883030164933060982083570835869719819168,
                9543924542455805865677785465159349894279659454147026211356195301797094705807,
                20459688264762308310588269661274938525104694421730310554970214541176968393385,
                19465560217230762055900455536522601853894771406309777885817297488125148793229,
                14344921588710038019110518519527661247161785735962037005430040319326557952203,
                1404059666412774300404055719909964693738831005230889414572223472408856431918);
        (int m3_0,int m3_1,int m3_2,int m3_3,int m3_4,int m3_5,int m3_6,int m3_7,int m3_8,int m3_9,int m3_10,int m3_11) =
            millerSingle(
                13700863412905423759250606799218875849166292978636329233814994817818554546431,
                21761028412726985313317130874134828290145951226051416150723277301116006118078,
                21547676276454546410296902538495425432829390494566673627605034971294784210249,
                6398877257285935365249802814125273995578953055511620955996813742572019651748,
                vkxX, vkxY);
        (int m4_0,int m4_1,int m4_2,int m4_3,int m4_4,int m4_5,int m4_6,int m4_7,int m4_8,int m4_9,int m4_10,int m4_11) =
            millerSingle(
                15825285363846036862295217228464959249112247579247978462621447842724817286232,
                3543600181522862329564888283473085279940669956506060026762005346996341806108,
                21514667205241674535457714632061047258097217169787877277363751636045743019390,
                10670741793215758088800930336726579942257175283397977169474518534600570072949,
                Cx, Cy);
        (int ab0,int ab1,int ab2,int ab3,int ab4,int ab5,int ab6,int ab7,int ab8,int ab9,int ab10,int ab11) =
            fp12Mul(m1_0,m1_1,m1_2,m1_3,m1_4,m1_5,m1_6,m1_7,m1_8,m1_9,m1_10,m1_11, m2_0,m2_1,m2_2,m2_3,m2_4,m2_5,m2_6,m2_7,m2_8,m2_9,m2_10,m2_11);
        (int abc0,int abc1,int abc2,int abc3,int abc4,int abc5,int abc6,int abc7,int abc8,int abc9,int abc10,int abc11) =
            fp12Mul(ab0,ab1,ab2,ab3,ab4,ab5,ab6,ab7,ab8,ab9,ab10,ab11, m3_0,m3_1,m3_2,m3_3,m3_4,m3_5,m3_6,m3_7,m3_8,m3_9,m3_10,m3_11);
        (int bnd0,int bnd1,int bnd2,int bnd3,int bnd4,int bnd5,int bnd6,int bnd7,int bnd8,int bnd9,int bnd10,int bnd11) =
            fp12Mul(abc0,abc1,abc2,abc3,abc4,abc5,abc6,abc7,abc8,abc9,abc10,abc11, m4_0,m4_1,m4_2,m4_3,m4_4,m4_5,m4_6,m4_7,m4_8,m4_9,m4_10,m4_11);
        (int o0,int o1,int o2,int o3,int o4,int o5,int o6,int o7,int o8,int o9,int o10,int o11) =
            finalExp(bnd0,bnd1,bnd2,bnd3,bnd4,bnd5,bnd6,bnd7,bnd8,bnd9,bnd10,bnd11);
        require(o0==1); require(o1==0); require(o2==0); require(o3==0); require(o4==0); require(o5==0);
        require(o6==0); require(o7==0); require(o8==0); require(o9==0); require(o10==0); require(o11==0);
    }
}

sources.lib/Miller.cash:
pragma cashscript ^0.14.0;

// BN254 Miller-loop machinery (divisive twist): G2 projective point ops (pointDouble / pointAdd) that
// return the 3 line coefficients + new R, the line application, the psi (untwist-Frobenius) map, and
// the full single-pair Miller loop. Builds on Fp12.cash (which carries the whole field tower).
import "./Fp12.cash";

// pointDouble: returns [c0,c1,c2 (line), newR] = 12 ints
function pointDouble(int Xa,int Xb,int Ya,int Yb,int Za,int Zb)
    returns (int,int,int,int,int,int, int,int,int,int,int,int) {
    (int t0a,int t0b) = fp2Sqr(Ya, Yb);
    (int t1a,int t1b) = fp2Sqr(Za, Zb);
    (int s1a,int s1b) = fp2Scale(t1a, t1b, 3);
    (int t2a,int t2b) = fp2MulByB(s1a, s1b);
    (int t3a,int t3b) = fp2Scale(t2a, t2b, 3);
    (int yza,int yzb) = fp2Add(Ya, Yb, Za, Zb);
    (int sq_a,int sq_b) = fp2Sqr(yza, yzb);
    (int u4a,int u4b) = fp2Sub(sq_a, sq_b, t1a, t1b);
    (int t4a,int t4b) = fp2Sub(u4a, u4b, t0a, t0b);
    (int c0a,int c0b) = fp2Sub(t2a, t2b, t0a, t0b);
    (int rxq_a,int rxq_b) = fp2Sqr(Xa, Xb);
    (int c1a,int c1b) = fp2Scale(rxq_a, rxq_b, 3);
    (int c2a,int c2b) = fp2Neg(t4a, t4b);
    (int da,int db) = fp2Sub(t0a, t0b, t3a, t3b);
    (int dxa,int dxb) = fp2Mul(da, db, Xa, Xb);
    (int dxya,int dxyb) = fp2Mul(dxa, dxb, Ya, Yb);
    (int nxa,int nxb) = fp2Half(dxya, dxyb);
    (int sa,int sb) = fp2Add(t0a, t0b, t3a, t3b);
    (int sha,int shb) = fp2Half(sa, sb);
    (int sh2a,int sh2b) = fp2Sqr(sha, shb);
    (int t2sa,int t2sb) = fp2Sqr(t2a, t2b);
    (int t2s3a,int t2s3b) = fp2Scale(t2sa, t2sb, 3);
    (int nya,int nyb) = fp2Sub(sh2a, sh2b, t2s3a, t2s3b);
    (int nza,int nzb) = fp2Mul(t0a, t0b, t4a, t4b);
    return c0a,c0b,c1a,c1b,c2a,c2b, nxa,nxb,nya,nyb,nza,nzb;
}

// pointAdd: R + Q (Q affine), returns [c0,c1,c2 (line), newR] = 12 ints
function pointAdd(int Xa,int Xb,int Ya,int Yb,int Za,int Zb, int Qxa,int Qxb,int Qya,int Qyb)
    returns (int,int,int,int,int,int, int,int,int,int,int,int) {
    (int qyz_a,int qyz_b) = fp2Mul(Qya, Qyb, Za, Zb);
    (int t0a,int t0b) = fp2Sub(Ya, Yb, qyz_a, qyz_b);
    (int qxz_a,int qxz_b) = fp2Mul(Qxa, Qxb, Za, Zb);
    (int t1a,int t1b) = fp2Sub(Xa, Xb, qxz_a, qxz_b);
    (int t0qx_a,int t0qx_b) = fp2Mul(t0a, t0b, Qxa, Qxb);
    (int t1qy_a,int t1qy_b) = fp2Mul(t1a, t1b, Qya, Qyb);
    (int c0a,int c0b) = fp2Sub(t0qx_a, t0qx_b, t1qy_a, t1qy_b);
    (int c1a,int c1b) = fp2Neg(t0a, t0b);
    int c2a = t1a;
    int c2b = t1b;
    (int t2a,int t2b) = fp2Sqr(t1a, t1b);
    (int t3a,int t3b) = fp2Mul(t2a, t2b, t1a, t1b);
    (int t4a,int t4b) = fp2Mul(t2a, t2b, Xa, Xb);
    (int t42a,int t42b) = fp2Scale(t4a, t4b, 2);
    (int d35a,int d35b) = fp2Sub(t3a, t3b, t42a, t42b);
    (int t0sa,int t0sb) = fp2Sqr(t0a, t0b);
    (int t0sza,int t0szb) = fp2Mul(t0sa, t0sb, Za, Zb);
    (int t5a,int t5b) = fp2Add(d35a, d35b, t0sza, t0szb);
    (int nxa,int nxb) = fp2Mul(t1a, t1b, t5a, t5b);
    (int d45a,int d45b) = fp2Sub(t4a, t4b, t5a, t5b);
    (int d45t0a,int d45t0b) = fp2Mul(d45a, d45b, t0a, t0b);
    (int t3rya,int t3ryb) = fp2Mul(t3a, t3b, Ya, Yb);
    (int nya,int nyb) = fp2Sub(d45t0a, d45t0b, t3rya, t3ryb);
    (int nza,int nzb) = fp2Mul(Za, Zb, t3a, t3b);
    return c0a,c0b,c1a,c1b,c2a,c2b, nxa,nxb,nya,nyb,nza,nzb;
}

// line application (divisive twist): f = mul034(f, c2*Py, c1*Px, c0)
function line(
    int F0,int F1,int F2,int F3,int F4,int F5,int F6,int F7,int F8,int F9,int F10,int F11,
    int c0a,int c0b,int c1a,int c1b,int c2a,int c2b, int Px, int Py
) returns (int,int,int,int,int,int,int,int,int,int,int,int) {
    int o0a = mulFp(c2a, Py);
    int o0b = mulFp(c2b, Py);
    int o3a = mulFp(c1a, Px);
    int o3b = mulFp(c1b, Px);
    (int r0,int r1,int r2,int r3,int r4,int r5,int r6,int r7,int r8,int r9,int r10,int r11) =
        mul034(F0,F1,F2,F3,F4,F5,F6,F7,F8,F9,F10,F11, o0a,o0b, o3a,o3b, c0a,c0b);
    return r0,r1,r2,r3,r4,r5,r6,r7,r8,r9,r10,r11;
}

// psi (untwist-Frobenius-twist): x' = conj(x)*PSI_X, y' = conj(y)*PSI_Y
function psi(int xa,int xb,int ya,int yb) returns (int,int,int,int) {
    (int cxa,int cxb) = fp2Conj(xa, xb);
    (int pxa,int pxb) = fp2Mul(cxa, cxb,
        21575463638280843010398324269430826099269044274347216827212613867836435027261,
        10307601595873709700152284273816112264069230130616436755625194854815875713954);
    (int cya,int cyb) = fp2Conj(ya, yb);
    (int pya,int pyb) = fp2Mul(cya, cyb,
        2821565182194536844548159561693502659359617185244120367078079554186484126554,
        3505843767911556378687030309984248845540243509899259641013678093033130930403);
    return pxa, pxb, pya, pyb;
}

// Full optimal-ate Miller loop for one pair e(P in G1, Q in G2) -> Fp12 (pre-final-exp).
function millerSingle(int Qxa,int Qxb,int Qya,int Qyb, int Px, int Py)
    returns (int,int,int,int,int,int,int,int,int,int,int,int) {
    int F0=1; int F1=0; int F2=0; int F3=0; int F4=0; int F5=0;
    int F6=0; int F7=0; int F8=0; int F9=0; int F10=0; int F11=0;
    int Rxa=Qxa; int Rxb=Qxb; int Rya=Qya; int Ryb=Qyb; int Rza=1; int Rzb=0;

    for (int k = 0; k < 65; k = k + 1) {
        (F0,F1,F2,F3,F4,F5,F6,F7,F8,F9,F10,F11) =
            fp12Sqr(F0,F1,F2,F3,F4,F5,F6,F7,F8,F9,F10,F11);
        (int dc0,int dc1,int dc2,int dc3,int dc4,int dc5, Rxa,Rxb,Rya,Ryb,Rza,Rzb) =
            pointDouble(Rxa,Rxb,Rya,Ryb,Rza,Rzb);
        (F0,F1,F2,F3,F4,F5,F6,F7,F8,F9,F10,F11) =
            line(F0,F1,F2,F3,F4,F5,F6,F7,F8,F9,F10,F11, dc0,dc1,dc2,dc3,dc4,dc5, Px, Py);
        int nz = (3045737938581365386 >> k) % 2;
        if (nz == 1) {
            int neg = (162306075919524482 >> k) % 2;
            int uya = Qya;
            int uyb = Qyb;
            if (neg == 1) { (uya,uyb) = fp2Neg(Qya, Qyb);}
            (int ac0,int ac1,int ac2,int ac3,int ac4,int ac5, Rxa,Rxb,Rya,Ryb,Rza,Rzb) =
                pointAdd(Rxa,Rxb,Rya,Ryb,Rza,Rzb, Qxa,Qxb,uya,uyb);
            (F0,F1,F2,F3,F4,F5,F6,F7,F8,F9,F10,F11) =
                line(F0,F1,F2,F3,F4,F5,F6,F7,F8,F9,F10,F11, ac0,ac1,ac2,ac3,ac4,ac5, Px, Py);
        }
    }

    (int q1xa,int q1xb,int q1ya,int q1yb) = psi(Qxa,Qxb,Qya,Qyb);
    (int bc0,int bc1,int bc2,int bc3,int bc4,int bc5, Rxa,Rxb,Rya,Ryb,Rza,Rzb) =
        pointAdd(Rxa,Rxb,Rya,Ryb,Rza,Rzb, q1xa,q1xb,q1ya,q1yb);
    (F0,F1,F2,F3,F4,F5,F6,F7,F8,F9,F10,F11) =
        line(F0,F1,F2,F3,F4,F5,F6,F7,F8,F9,F10,F11, bc0,bc1,bc2,bc3,bc4,bc5, Px, Py);

    (int q2xa,int q2xb,int q2ya,int q2yb) = psi(q1xa,q1xb,q1ya,q1yb);
    (int q2nya,int q2nyb) = fp2Neg(q2ya, q2yb);
    (int cc0,int cc1,int cc2,int cc3,int cc4,int cc5, Rxa,Rxb,Rya,Ryb,Rza,Rzb) =
        pointAdd(Rxa,Rxb,Rya,Ryb,Rza,Rzb, q2xa,q2xb,q2nya,q2nyb);
    (int j0,int j1,int j2,int j3,int j4,int j5,int j6,int j7,int j8,int j9,int j10,int j11) =
        line(F0,F1,F2,F3,F4,F5,F6,F7,F8,F9,F10,F11, cc0,cc1,cc2,cc3,cc4,cc5, Px, Py);

    return j0,j1,j2,j3,j4,j5,j6,j7,j8,j9,j10,j11;
}

// ---- G2 subgroup membership (EIP-197): Jacobian group law over Fp2 (a=0) for [6x^2]B == psi(B) ----
function g2Double(int Xa,int Xb,int Ya,int Yb,int Za,int Zb) returns (int,int,int,int,int,int) {
    (int Aa,int Ab) = fp2Sqr(Xa, Xb);
    (int Bb0,int Bb1) = fp2Sqr(Ya, Yb);
    (int Ca,int Cb) = fp2Sqr(Bb0, Bb1);
    (int xpa,int xpb) = fp2Add(Xa, Xb, Bb0, Bb1);
    (int sqa,int sqb) = fp2Sqr(xpa, xpb);
    (int t1a,int t1b) = fp2Sub(sqa, sqb, Aa, Ab);
    (int t2a,int t2b) = fp2Sub(t1a, t1b, Ca, Cb);
    (int Da,int Db) = fp2Sc(t2a, t2b, 2);
    (int Ea,int Eb) = fp2Sc(Aa, Ab, 3);
    (int Fa,int Fb) = fp2Sqr(Ea, Eb);
    (int twoDa,int twoDb) = fp2Sc(Da, Db, 2);
    (int nXa,int nXb) = fp2Sub(Fa, Fb, twoDa, twoDb);
    (int dmxa,int dmxb) = fp2Sub(Da, Db, nXa, nXb);
    (int ednma,int ednmb) = fp2Mul(Ea, Eb, dmxa, dmxb);
    (int c8a,int c8b) = fp2Sc(Ca, Cb, 8);
    (int nYa,int nYb) = fp2Sub(ednma, ednmb, c8a, c8b);
    (int yza,int yzb) = fp2Mul(Ya, Yb, Za, Zb);
    (int nZa,int nZb) = fp2Sc(yza, yzb, 2);
    return nXa,nXb,nYa,nYb,nZa,nZb;
}
function g2AddAffine(int Xa,int Xb,int Ya,int Yb,int Za,int Zb, int bXa,int bXb,int bYa,int bYb) returns (int,int,int,int,int,int) {
    int rXa = bXa; int rXb = bXb; int rYa = bYa; int rYb = bYb; int rZa = 1; int rZb = 0;
    if (Za != 0 || Zb != 0) {
        (int z11a,int z11b) = fp2Sqr(Za, Zb);
        (int u2a,int u2b) = fp2Mul(bXa, bXb, z11a, z11b);
        (int z11za,int z11zb) = fp2Mul(z11a, z11b, Za, Zb);
        (int s2a,int s2b) = fp2Mul(bYa, bYb, z11za, z11zb);
        if (Xa == u2a && Xb == u2b && Ya == s2a && Yb == s2b) {
            (rXa,rXb,rYa,rYb,rZa,rZb) = g2Double(Xa, Xb, Ya, Yb, Za, Zb);
        } else {
            (int ha,int hb) = fp2Sub(u2a, u2b, Xa, Xb);
            (int i2a,int i2b) = fp2Sqr(mulFp(2, ha), mulFp(2, hb));
            (int ja,int jb) = fp2Mul(ha, hb, i2a, i2b);
            (int rsa,int rsb) = fp2Sub(s2a, s2b, Ya, Yb);
            (int rra,int rrb) = fp2Sc(rsa, rsb, 2);
            (int va,int vb) = fp2Mul(Xa, Xb, i2a, i2b);
            (int rr2a,int rr2b) = fp2Sqr(rra, rrb);
            (int rr2ja,int rr2jb) = fp2Sub(rr2a, rr2b, ja, jb);
            (int v2a,int v2b) = fp2Sc(va, vb, 2);
            (int nXa,int nXb) = fp2Sub(rr2ja, rr2jb, v2a, v2b);
            (int vmxa,int vmxb) = fp2Sub(va, vb, nXa, nXb);
            (int rvma,int rvmb) = fp2Mul(rra, rrb, vmxa, vmxb);
            (int yja,int yjb) = fp2Mul(Ya, Yb, ja, jb);
            (int yj2a,int yj2b) = fp2Sc(yja, yjb, 2);
            (int nYa,int nYb) = fp2Sub(rvma, rvmb, yj2a, yj2b);
            (int zp1a,int zp1b) = fp2Add(Za, Zb, 1, 0);
            (int zp1sa,int zp1sb) = fp2Sqr(zp1a, zp1b);
            (int t3a,int t3b) = fp2Sub(zp1sa, zp1sb, z11a, z11b);
            (int t4a,int t4b) = fp2Sub(t3a, t3b, 1, 0);
            (int nZa,int nZb) = fp2Mul(t4a, t4b, ha, hb);
            rXa=nXa; rXb=nXb; rYa=nYa; rYb=nYb; rZa=nZa; rZb=nZb;
        }
    }
    return rXa, rXb, rYa, rYb, rZa, rZb;
}

sources.lib/Fp12.cash:
pragma cashscript ^0.14.0;

// BN254 Fp12 = Fp6[w]/(w^2 - v), gamma = v = Fp6 non-residue (noble basis).
// An Fp12 element is (c0, c1) with each ci an Fp6 (= 6 ints) -> 12 ints in noble serialization order.
// This file covers mul / sqr / conjugate; Frobenius maps + inverse are appended for the higher
// layers (final exponentiation). Builds on Fp6.cash.
import "./Fp6.cash";

// sparse Fp12 multiply f * (o0, 0, 0, o3, o4, 0) — the Miller-loop line application (mul034).
function mul034(
    int F0,int F1,int F2,int F3,int F4,int F5, int F6,int F7,int F8,int F9,int F10,int F11,
    int o0a,int o0b, int o3a,int o3b, int o4a,int o4b
) returns (int,int,int,int,int,int,int,int,int,int,int,int) {
    (int A0,int A1) = fp2Mul(F0, F1, o0a, o0b);
    (int A2,int A3) = fp2Mul(F2, F3, o0a, o0b);
    (int A4,int A5) = fp2Mul(F4, F5, o0a, o0b);
    (int B0,int B1,int B2,int B3,int B4,int B5) = fp6Mul01(F6,F7,F8,F9,F10,F11, o3a,o3b, o4a,o4b);
    (int S0,int S1,int S2,int S3,int S4,int S5) = fp6Add(F0,F1,F2,F3,F4,F5, F6,F7,F8,F9,F10,F11);
    (int qa,int qb) = fp2Add(o0a, o0b, o3a, o3b);
    (int G0,int G1,int G2,int G3,int G4,int G5) = fp6Mul01(S0,S1,S2,S3,S4,S5, qa,qb, o4a,o4b);
    (int VB0,int VB1,int VB2,int VB3,int VB4,int VB5) = fp6MulByV(B0,B1,B2,B3,B4,B5);
    (int C0,int C1,int C2,int C3,int C4,int C5) = fp6Add(VB0,VB1,VB2,VB3,VB4,VB5, A0,A1,A2,A3,A4,A5);
    (int AB0,int AB1,int AB2,int AB3,int AB4,int AB5) = fp6Add(A0,A1,A2,A3,A4,A5, B0,B1,B2,B3,B4,B5);
    (int C6,int C7,int C8,int C9,int C10,int C11) = fp6Sub(G0,G1,G2,G3,G4,G5, AB0,AB1,AB2,AB3,AB4,AB5);
    return C0,C1,C2,C3,C4,C5,C6,C7,C8,C9,C10,C11;
}
// (a0 + a1 w)(b0 + b1 w) = (a0 b0 + v a1 b1) + ((a0+a1)(b0+b1) - a0 b0 - a1 b1) w
function fp12Mul(
    int A0,int A1,int A2,int A3,int A4,int A5, int A6,int A7,int A8,int A9,int A10,int A11,
    int B0,int B1,int B2,int B3,int B4,int B5, int B6,int B7,int B8,int B9,int B10,int B11
) returns (int,int,int,int,int,int,int,int,int,int,int,int) {
    (int t0_0,int t0_1,int t0_2,int t0_3,int t0_4,int t0_5) =
        fp6Mul(A0,A1,A2,A3,A4,A5, B0,B1,B2,B3,B4,B5);
    (int t1_0,int t1_1,int t1_2,int t1_3,int t1_4,int t1_5) =
        fp6Mul(A6,A7,A8,A9,A10,A11, B6,B7,B8,B9,B10,B11);
    (int vt_0,int vt_1,int vt_2,int vt_3,int vt_4,int vt_5) =
        fp6MulByV(t1_0,t1_1,t1_2,t1_3,t1_4,t1_5);
    (int C0,int C1,int C2,int C3,int C4,int C5) =
        fp6Add(t0_0,t0_1,t0_2,t0_3,t0_4,t0_5, vt_0,vt_1,vt_2,vt_3,vt_4,vt_5);
    (int sa_0,int sa_1,int sa_2,int sa_3,int sa_4,int sa_5) =
        fp6Add(A0,A1,A2,A3,A4,A5, A6,A7,A8,A9,A10,A11);
    (int sb_0,int sb_1,int sb_2,int sb_3,int sb_4,int sb_5) =
        fp6Add(B0,B1,B2,B3,B4,B5, B6,B7,B8,B9,B10,B11);
    (int pr_0,int pr_1,int pr_2,int pr_3,int pr_4,int pr_5) =
        fp6Mul(sa_0,sa_1,sa_2,sa_3,sa_4,sa_5, sb_0,sb_1,sb_2,sb_3,sb_4,sb_5);
    (int q_0,int q_1,int q_2,int q_3,int q_4,int q_5) =
        fp6Sub(pr_0,pr_1,pr_2,pr_3,pr_4,pr_5, t0_0,t0_1,t0_2,t0_3,t0_4,t0_5);
    (int C6,int C7,int C8,int C9,int C10,int C11) =
        fp6Sub(q_0,q_1,q_2,q_3,q_4,q_5, t1_0,t1_1,t1_2,t1_3,t1_4,t1_5);
    return C0,C1,C2,C3,C4,C5,C6,C7,C8,C9,C10,C11;
}

function fp12Sqr(
    int A0,int A1,int A2,int A3,int A4,int A5, int A6,int A7,int A8,int A9,int A10,int A11
) returns (int,int,int,int,int,int,int,int,int,int,int,int) {
    (int C0,int C1,int C2,int C3,int C4,int C5,int C6,int C7,int C8,int C9,int C10,int C11) =
        fp12Mul(A0,A1,A2,A3,A4,A5,A6,A7,A8,A9,A10,A11, A0,A1,A2,A3,A4,A5,A6,A7,A8,A9,A10,A11);
    return C0,C1,C2,C3,C4,C5,C6,C7,C8,C9,C10,C11;
}

// conjugate over Fp12: (c0, -c1)
function fp12Conj(
    int A0,int A1,int A2,int A3,int A4,int A5, int A6,int A7,int A8,int A9,int A10,int A11
) returns (int,int,int,int,int,int,int,int,int,int,int,int) {
    (int N6,int N7,int N8,int N9,int N10,int N11) = fp6Neg(A6,A7,A8,A9,A10,A11);
    return A0,A1,A2,A3,A4,A5,N6,N7,N8,N9,N10,N11;
}

// inverse: den = c0^2 - v*c1^2;  t = fp6Inv(den);  (c0 t, -(c1 t))
function fp12Inv(
    int A0,int A1,int A2,int A3,int A4,int A5, int A6,int A7,int A8,int A9,int A10,int A11
) returns (int,int,int,int,int,int,int,int,int,int,int,int) {
    (int sc0_0,int sc0_1,int sc0_2,int sc0_3,int sc0_4,int sc0_5) = fp6Sqr(A0,A1,A2,A3,A4,A5);
    (int sc1_0,int sc1_1,int sc1_2,int sc1_3,int sc1_4,int sc1_5) = fp6Sqr(A6,A7,A8,A9,A10,A11);
    (int vc_0,int vc_1,int vc_2,int vc_3,int vc_4,int vc_5) = fp6MulByV(sc1_0,sc1_1,sc1_2,sc1_3,sc1_4,sc1_5);
    (int dn_0,int dn_1,int dn_2,int dn_3,int dn_4,int dn_5) =
        fp6Sub(sc0_0,sc0_1,sc0_2,sc0_3,sc0_4,sc0_5, vc_0,vc_1,vc_2,vc_3,vc_4,vc_5);
    (int t_0,int t_1,int t_2,int t_3,int t_4,int t_5) = fp6Inv(dn_0,dn_1,dn_2,dn_3,dn_4,dn_5);
    (int n0,int n1,int n2,int n3,int n4,int n5) =
        fp6Mul(A0,A1,A2,A3,A4,A5, t_0,t_1,t_2,t_3,t_4,t_5);
    (int p0,int p1,int p2,int p3,int p4,int p5) =
        fp6Mul(A6,A7,A8,A9,A10,A11, t_0,t_1,t_2,t_3,t_4,t_5);
    (int w0,int w1,int w2,int w3,int w4,int w5) = fp6Neg(p0,p1,p2,p3,p4,p5);
    return n0,n1,n2,n3,n4,n5,w0,w1,w2,w3,w4,w5;
}

// Frobenius a -> a^(p^k), k = 1,2,3. FP6_C1/FP6_C2 and FP12_C1 are precomputed Fp2 constants.
function fp12Frob1(
    int A0,int A1,int A2,int A3,int A4,int A5, int A6,int A7,int A8,int A9,int A10,int A11
) returns (int,int,int,int,int,int,int,int,int,int,int,int) {
    (int c0,int c1,int c2,int c3,int c4,int c5) = fp6FrobOdd(
        A0,A1,A2,A3,A4,A5,
        21575463638280843010398324269430826099269044274347216827212613867836435027261, 10307601595873709700152284273816112264069230130616436755625194854815875713954,
        2581911344467009335267311115468803099551665605076196740867805258568234346338, 19937756971775647987995932169929341994314640652964949448313374472400716661030);
    (int g0,int g1,int g2,int g3,int g4,int g5) = fp6FrobOdd(
        A6,A7,A8,A9,A10,A11,
        21575463638280843010398324269430826099269044274347216827212613867836435027261, 10307601595873709700152284273816112264069230130616436755625194854815875713954,
        2581911344467009335267311115468803099551665605076196740867805258568234346338, 19937756971775647987995932169929341994314640652964949448313374472400716661030);
    (int f0,int f1,int f2,int f3,int f4,int f5) = fp6MulByFp2(
        g0,g1,g2,g3,g4,g5,
        8376118865763821496583973867626364092589906065868298776909617916018768340080, 16469823323077808223889137241176536799009286646108169935659301613961712198316);
    return c0,c1,c2,c3,c4,c5,f0,f1,f2,f3,f4,f5;
}
function fp12Frob2(
    int A0,int A1,int A2,int A3,int A4,int A5, int A6,int A7,int A8,int A9,int A10,int A11
) returns (int,int,int,int,int,int,int,int,int,int,int,int) {
    (int c0,int c1,int c2,int c3,int c4,int c5) = fp6FrobEven(
        A0,A1,A2,A3,A4,A5,
        21888242871839275220042445260109153167277707414472061641714758635765020556616, 0,
        2203960485148121921418603742825762020974279258880205651966, 0);
    (int g0,int g1,int g2,int g3,int g4,int g5) = fp6FrobEven(
        A6,A7,A8,A9,A10,A11,
        21888242871839275220042445260109153167277707414472061641714758635765020556616, 0,
        2203960485148121921418603742825762020974279258880205651966, 0);
    (int f0,int f1,int f2,int f3,int f4,int f5) = fp6MulByFp2(
        g0,g1,g2,g3,g4,g5,
        21888242871839275220042445260109153167277707414472061641714758635765020556617, 0);
    return c0,c1,c2,c3,c4,c5,f0,f1,f2,f3,f4,f5;
}
function fp12Frob3(
    int A0,int A1,int A2,int A3,int A4,int A5, int A6,int A7,int A8,int A9,int A10,int A11
) returns (int,int,int,int,int,int,int,int,int,int,int,int) {
    (int c0,int c1,int c2,int c3,int c4,int c5) = fp6FrobOdd(
        A0,A1,A2,A3,A4,A5,
        3772000881919853776433695186713858239009073593817195771773381919316419345261, 2236595495967245188281701248203181795121068902605861227855261137820944008926,
        5324479202449903542726783395506214481928257762400643279780343368557297135718, 16208900380737693084919495127334387981393726419856888799917914180988844123039);
    (int g0,int g1,int g2,int g3,int g4,int g5) = fp6FrobOdd(
